'use strict';
// bot_bridge 本地桩：schemastery 的最小实现。
// 用 Proxy 兜底：schema 的静态构造器与链式方法名是开放的（不同版本不尽相同），
// 任何未知属性都返回可继续链式调用的 SchemaLike。校验语义不实现（桥接下配置由
// N.E.K.O 侧提供），目标是插件模块求值时 `Schema.intersect([...])` 这类表达式不崩。

function SchemaLike(kind) {
  this.kind = kind || 'any';
  this._inner = [];
  this.required = false;
}

/** 链式方法：全部返回自身（串接任意深度的声明）。 */
const CHAIN_METHODS = [
  'description', 'required', 'default', 'i18n', 'role', 'pattern', 'hidden',
  'disabled', 'max', 'min', 'step', 'experimental', 'debounce', 'comment',
  'collapse', 'lov', 'set', 'extends', 'computed', 'tolist', 'pick', 'omit',
];
for (const method of CHAIN_METHODS) {
  SchemaLike.prototype[method] = function () { return this; };
}
SchemaLike.prototype.toJSON = function () {
  return { kind: this.kind, inner: this._inner.length };
};

const STATIC_KINDS = [
  'object', 'intersect', 'union', 'array', 'dict', 'tuple', 'string', 'number',
  'boolean', 'const', 'any', 'natural', 'percent', 'date', 'regexp',
];

function makeSchema(kind) { return new SchemaLike(kind); }

const Schema = new Proxy(function Schema(..._args) { return makeSchema('any'); }, {
  get(target, prop) {
    if (typeof prop === 'symbol') return target[prop];
    if (prop in target) return target[prop];
    if (prop === 'isSchema') return (value) => value instanceof SchemaLike;
    return (..._args) => makeSchema(String(prop));
  },
  has() { return true; },
});

module.exports = Schema;
module.exports.default = Schema;
module.exports.Schema = Schema;
module.exports.SchemaLike = SchemaLike;
module.exports.makeSchema = makeSchema;
